//! Std-only smoke runs of the `pkg_*` libFuzzer targets
//! (`fuzz/fuzz_targets/`): the same harness code (`fuzz/harness/pkg_*.rs`,
//! included by path) driven by the deterministic mutator in
//! `fuzz/harness/smoke.rs` over the committed seed corpora. See
//! `fuzz/README.md`. `ROBODR_FUZZ_ITERS` / `ROBODR_FUZZ_SECS` tune the runs.
//!
//! The seeds are generated by the harnesses (`seeds()`, signed with the
//! harness site's fixed keys; Ed25519 is deterministic) and written by
//! `regenerate_seeds` (run with `--ignored`); `seeds_are_current` fails
//! when the committed files differ, and `seeds_take_the_success_paths`
//! checks they still reach the verified paths, so a format change cannot
//! silently turn the corpus into garbage.

// Each `pkg_*` harness includes `fuzz/harness/pkg_common.rs` itself, so
// every libFuzzer binary stands alone; this test links all five harnesses
// and so holds five private copies of that helper module, by design.
#![allow(clippy::duplicate_mod)]

#[path = "../../../fuzz/harness/pkg_bundle.rs"]
mod pkg_bundle;
#[path = "../../../fuzz/harness/pkg_deployment.rs"]
mod pkg_deployment;
#[path = "../../../fuzz/harness/pkg_parity.rs"]
mod pkg_parity;
#[path = "../../../fuzz/harness/pkg_rpk.rs"]
mod pkg_rpk;
#[path = "../../../fuzz/harness/pkg_trust.rs"]
mod pkg_trust;
#[path = "../../../fuzz/harness/smoke.rs"]
mod smoke;

const DIR: &str = env!("CARGO_MANIFEST_DIR");
/// The harness site (`fuzz/harness/pkg_common.rs`).
const SITE: &str = "site-f";

type Seeds = fn() -> Vec<(&'static str, Vec<u8>)>;

const TARGETS: [(&str, Seeds); 5] = [
    ("pkg_rpk", pkg_rpk::seeds),
    ("pkg_bundle", pkg_bundle::seeds),
    ("pkg_deployment", pkg_deployment::seeds),
    ("pkg_trust", pkg_trust::seeds),
    ("pkg_parity", pkg_parity::seeds),
];

#[test]
#[ignore = "writes fuzz/corpus/pkg_*; run after a format change"]
fn regenerate_seeds() {
    for (t, seeds) in TARGETS {
        let dir = smoke::corpus_dir(DIR, t);
        std::fs::create_dir_all(&dir).unwrap();
        for (name, bytes) in seeds() {
            std::fs::write(dir.join(name), bytes).unwrap();
        }
    }
}

#[test]
fn seeds_are_current() {
    for (t, seeds) in TARGETS {
        for (name, bytes) in seeds() {
            let p = smoke::corpus_dir(DIR, t).join(name);
            let on_disk = std::fs::read(&p)
                .unwrap_or_else(|e| panic!("{}: {e} (run regenerate_seeds)", p.display()));
            assert!(
                on_disk == bytes,
                "{} is stale: run regenerate_seeds",
                p.display()
            );
        }
    }
}

fn parts(d: &[u8]) -> Vec<&[u8]> {
    d.splitn(4, |&b| b == 0).collect()
}

#[test]
fn seeds_take_the_success_paths() {
    use robodr_pkg::Code;
    let now = 1_790_000_100;
    let t = pkg_rpk_trust();
    let s = smoke::corpus(DIR, "pkg_rpk");
    let ok: Vec<_> = s
        .iter()
        .map(|d| {
            let p = parts(d);
            robodr_pkg::rpk::parse_manifest(p[0]).unwrap();
            robodr_pkg::rpk::verify_manifest(p[0], p[1], &t, now).map_err(|e| e.code)
        })
        .collect();
    assert!(ok.contains(&Err(Code::QuorumNotMet)) && ok.iter().any(|r| r.is_ok()));
    for d in smoke::corpus(DIR, "pkg_bundle") {
        let p = parts(&d);
        robodr_pkg::bundle::parse_bundle(p[0]).unwrap();
        let r = robodr_pkg::bundle::verify_bundle_manifest(p[0], p[1], &t);
        assert!(r.is_ok() || r.unwrap_err().code == Code::QuorumNotMet);
    }
    let dep: Vec<_> = smoke::corpus(DIR, "pkg_deployment")
        .iter()
        .map(|d| {
            let p = parts(d);
            robodr_pkg::deployment::verify_deployment(p[0], p[1], &t, now).map_err(|e| e.code)
        })
        .collect();
    assert!(dep.iter().any(|r| r.is_ok()) && dep.contains(&Err(Code::QuorumNotMet)));
    for d in smoke::corpus(DIR, "pkg_trust") {
        let p = parts(&d);
        let v = robodr_pkg::trust::verify_trust_pinned(p[0], p[1], &pkg_trust_pins(), SITE, now)
            .unwrap();
        robodr_pkg::trust::verify_trust_update(&v, p[2], p[3], now).unwrap();
    }
    for d in smoke::corpus(DIR, "pkg_parity") {
        pkg_parity::run(&d);
    }
}

fn pkg_rpk_trust() -> robodr_pkg::trust::VerifiedTrust {
    let (doc, sig) = pkg_trust_bytes();
    robodr_pkg::trust::verify_trust_pinned(&doc, &sig, &pkg_trust_pins(), SITE, 1_790_000_100)
        .unwrap()
}

fn pkg_trust_bytes() -> (Vec<u8>, Vec<u8>) {
    let d = &smoke::corpus(DIR, "pkg_trust")[0];
    let p = parts(d);
    (p[0].to_vec(), p[1].to_vec())
}

fn pkg_trust_pins() -> Vec<String> {
    (1..=3u8)
        .map(|i| {
            let k = robodr_blackbox::Ed25519SigningKey::from_seed(format!("root-{i}"), &[i; 32])
                .unwrap();
            robodr_pkg::common::fingerprint(&k.public_key())
        })
        .collect()
}

#[test]
fn pkg_rpk_smoke() {
    let seeds = smoke::corpus(DIR, "pkg_rpk");
    smoke::run("pkg_rpk", &seeds, 0x9e6_0001, &pkg_rpk::run);
}

